def bj_value(hand: list[str]) -> int:
    total, aces = 0, 0
    for c in hand:
        r = c[:-1]
        if r in ("J", "Q", "K"):
            total += 10
        elif r == "A":
            aces += 1
            total += 11
        else:
            total += int(r)
    while total > 21 and aces:
        total -= 10
        aces -= 1
    return total

