def git_pull() -> tuple[bool, str]:
    """Host-safe pull: stashes local changes (incl. untracked, e.g. SFTP uploads
    or Discord-made command JSONs) so merge never aborts, then restores them."""
    import subprocess as _sp

    def _run(*args):
        try:
            p = _sp.run(list(args), capture_output=True, text=True, timeout=60, cwd=str(BASE))
            return p.returncode, (p.stdout + p.stderr)[-1000:]
        except Exception as e:
            return 1, str(e)

    _run("git", "fetch", "origin")
    rc, out = _run("git", "diff", "--diff-filter=U", "--quiet")
    if rc != 0:
        return False, "unmerged conflict state (old SFTP upload?) — SSH in: git reset -q && git checkout -- . && git stash drop && git pull"
    _run("git", "stash", "push", "-u", "-m", "auto-update")
    rc, log = _run("git", "pull", "--ff-only")
    if rc == 0:
        _run("git", "stash", "pop")  # best-effort restore; ignored on conflict
    return rc == 0, log

def roulette_payout(kind: str, pick: str, win: int) -> int:
    """Pure: multiplier for a bet. kind: number|red|black|even|odd|high|low."""
    reds = {1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36}
    kind = kind.lower()
    if kind == "number":
        return 36 if str(win) == pick else 0
    if win == 0:
        return 0
    if kind == "red":
        return 2 if win in reds else 0
    if kind == "black":
        return 2 if win not in reds else 0
    if kind == "even":
        return 2 if win % 2 == 0 else 0
    if kind == "odd":
        return 2 if win % 2 == 1 else 0
    if kind == "high":
        return 2 if win >= 19 else 0
    if kind == "low":
        return 2 if win <= 18 else 0
    return 0

