def wordle_feedback(guess: str, answer: str) -> str:
    out, used = [], [False] * 5
    for i, c in enumerate(guess):
        if c == answer[i]:
            out.append("🟩")
            used[i] = True
        else:
            out.append(None)
    for i, c in enumerate(guess):
        if out[i] is None:
            hit = next((j for j in range(5) if not used[j] and answer[j] == c), None)
            if hit is None:
                out[i] = "⬛"
            else:
                used[hit] = True
                out[i] = "🟨"
    return "".join(out)

