def parse_code_arg(arg: str) -> tuple[str, str]:
    """!run py <code> | !run ```py\\ncode``` | !run <code> (defaults py)"""
    arg = arg.strip()
    if arg.startswith("```"):
        lines = arg.strip("`").split("\n", 1)
        lang = lines[0].strip().lower() if len(lines) > 1 and lines[0].strip().lower() in ("py", "python", "js") else "py"
        code = lines[1] if len(lines) > 1 and lang in ("py", "python", "js") else arg.strip("` \n")[2:].strip() if arg.startswith("```") else arg
        # simpler: strip fences
        if arg.startswith("```"):
            inner = arg[3:]
            if "\n" in inner:
                first, rest = inner.split("\n", 1)
                if first.strip().lower() in ("py", "python", "js", ""):
                    code = rest.rstrip("`").rstrip()
                    lang = first.strip().lower() or "py"
                else:
                    code = inner.rstrip("`").strip()
            else:
                code = inner.strip("` \n")
        return lang, code
    parts = arg.split(None, 1)
    if len(parts) == 2 and parts[0].lower() in ("py", "python"):
        return "py", parts[1]
    return "py", arg

