def roulette_payout(kind: str, pick: str, win: int) -> int:
    """Pure: multiplier for a bet. kind: number|red|black|even|odd|high|low."""
    reds = {1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36}
    kind = kind.lower()
    if kind == "number":
        return 36 if str(win) == pick else 0
    if win == 0:
        return 0
    if kind == "red":
        return 2 if win in reds else 0
    if kind == "black":
        return 2 if win not in reds else 0
    if kind == "even":
        return 2 if win % 2 == 0 else 0
    if kind == "odd":
        return 2 if win % 2 == 1 else 0
    if kind == "high":
        return 2 if win >= 19 else 0
    if kind == "low":
        return 2 if win <= 18 else 0
    return 0

